(function(root){
'use strict';
const GOODS={wood:'Holz',plank:'Bretter',fish:'Fisch',grain:'Getreide',flour:'Mehl',bread:'Brot',feed:'Futter',salt:'Salz',clay:'Lehm',brick:'Ziegel',beer:'Bier'};
const DEF={
road:{name:'Weg',cost:{},desc:'Verbindet Gebäude mit dem Hafen.',icon:'·'},
house:{name:'Wohnhaus',cost:{wood:6,plank:2},desc:'Vier neue Bewohner. Sie brauchen Nahrung.',icon:'⌂'},
wood:{name:'Holzfäller',cost:{wood:5},out:{wood:3},every:8,workers:2,resource:'forest',desc:'3 Holz alle 8 Sekunden. Benötigt Wald.',icon:'♠'},
saw:{name:'Sägewerk',cost:{wood:8},input:{wood:2},out:{plank:2},every:10,workers:2,desc:'2 Holz → 2 Bretter in 10 Sekunden.',icon:'▥'},
fish:{name:'Fischerhütte',cost:{wood:6},out:{fish:3},every:10,workers:2,resource:'fish',coast:true,desc:'3 Fisch alle 10 Sekunden. Nur am Ufer.',icon:'≈'},
farm:{name:'Bauernhof',cost:{wood:8,plank:4},out:{grain:3},every:12,workers:2,resource:'soil',desc:'3 Getreide oder Futter in 12 Sekunden. Anbau im Gebäudefenster wählen.',icon:'⚘'},
mill:{name:'Mühle',cost:{wood:8,plank:6},input:{grain:2},out:{flour:2},every:10,workers:2,desc:'2 Getreide → 2 Mehl in 10 Sekunden.',icon:'✣'},
bakery:{name:'Bäckerei',cost:{wood:6,plank:6},input:{flour:2,wood:1},out:{bread:4},every:12,workers:2,desc:'2 Mehl + 1 Holz → 4 Brot in 12 Sekunden.',icon:'◡'},
salt:{name:'Saline',cost:{wood:8,plank:4},input:{wood:1},out:{salt:3},every:12,workers:2,resource:'salt',desc:'1 Holz → 3 Salz. Nur bei Solevorkommen.',icon:'◇'},
clay:{name:'Lehmgrube',cost:{wood:6,plank:2},out:{clay:3},every:10,workers:2,resource:'clay',desc:'3 Lehm in 10 Sekunden. Nur am Lehmvorkommen.',icon:'▰'},
kiln:{name:'Ziegelei',cost:{wood:8,plank:6},input:{clay:2,wood:1},out:{brick:2},every:12,workers:2,desc:'2 Lehm + 1 Holz → 2 Ziegel.',icon:'▤'},
brew:{name:'Brauerei',cost:{wood:8,plank:10,brick:4},input:{grain:2,wood:1},out:{beer:2},every:15,workers:2,desc:'Vereinfachtes Rezept: 2 Getreide + 1 Holz → 2 Bier. Malz und Hopfen folgen später.',icon:'♜'}
};
function terrain(x,y){if(x<0||y<0||x>13||y>13)return 'water';const dx=(x-6.4)/6.4,dy=(y-6.6)/6.5;return dx*dx+dy*dy>0.93?'water':'land';}
function fresh(){return {version:1,time:0,paused:false,speed:1,tutorial:0,skip:false,selectedCity:0,deliveries:0,cities:[city(0)],routes:[],message:''};}
function city(id){return {id,name:['Lindenhavn','Salzwiek','Lehmau'][id],resources:[['forest','fish','soil'],['salt','forest'],['clay','soil']][id],stock:{wood:44,plank:22,fish:22,grain:8,flour:0,bread:0,feed:12,salt:0,clay:0,brick:0,beer:0},buildings:[{id:1,type:'harbor',x:6,y:11},{id:2,type:'road',x:6,y:10},{id:3,type:'road',x:6,y:9},{id:4,type:'house',x:5,y:9}],nextId:5,level:0,hunger:0};}
const at=(c,x,y)=>c.buildings.find(b=>b.x===x&&b.y===y);
function connected(c){let visited=new Set(),queue=c.buildings.filter(b=>b.type==='harbor').map(b=>[b.x,b.y]);while(queue.length){let [x,y]=queue.shift(),k=x+','+y;if(visited.has(k))continue;visited.add(k);for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){let b=at(c,x+dx,y+dy);if(b&&b.type==='road')queue.push([b.x,b.y]);}}return visited;}
function linked(c,b,set=connected(c)){return b.type==='harbor'||set.has(b.x+','+b.y)||[[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dy])=>set.has((b.x+dx)+','+(b.y+dy)));}
function population(c){return 8+c.buildings.filter(b=>b.type==='house'&&linked(c,b)).length*4;}
function assigned(c,b){let remaining=population(c);for(const a of c.buildings){let d=DEF[a.type];if(!d?.workers||!linked(c,a)||a.off)continue;remaining-=d.workers;if(a.id===b.id)return remaining>=0;}return false;}
function afford(stock,cost){return Object.entries(cost).every(([k,v])=>(stock[k]||0)>=v);}
function spend(stock,cost){for(let k in cost)stock[k]-=cost[k];}
function coast(x,y){return [[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dy])=>terrain(x+dx,y+dy)==='water');}
function place(c,type,x,y){let d=DEF[type];if(!d)return 'Unbekanntes Gebäude.';if(!Number.isInteger(x)||!Number.isInteger(y)||terrain(x,y)==='water')return 'Hier ist Wasser. Wähle eine freie Landfläche.';if(at(c,x,y))return 'Dieses Feld ist bereits belegt.';if(d.resource&&!c.resources.includes(d.resource))return 'Dieses Vorkommen gibt es hier nicht.';if(d.coast&&!coast(x,y))return 'Die Fischerhütte braucht einen Platz direkt am Ufer.';if(!afford(c.stock,d.cost))return 'Dafür fehlen Baustoffe.';spend(c.stock,d.cost);c.buildings.push({id:c.nextId++,type,x,y,progress:0,mode:'grain'});return '';}
function status(c,b){let d=DEF[b.type];if(!d?.out)return '';if(b.off)return 'Pausiert';if(!linked(c,b))return 'Weg zum Hafen fehlt';if(!assigned(c,b))return 'Arbeitskräfte fehlen';if(!afford(c.stock,d.input||{}))return 'Rohstoffe fehlen';let output=b.type==='farm'&&b.mode==='feed'?{feed:3}:d.out;if(Object.entries(output).some(([k,v])=>c.stock[k]+v>120))return 'Lager voll';return 'Produziert';}
function tick(s){if(s.paused)return;s.time++;for(const c of s.cities){for(const b of c.buildings){const d=DEF[b.type];if(!d?.out||status(c,b)!=='Produziert')continue;b.progress=(b.progress||0)+1;if(b.progress>=d.every){spend(c.stock,d.input||{});for(const [k,v]of Object.entries(b.type==='farm'&&b.mode==='feed'?{feed:3}:d.out))c.stock[k]+=v;b.progress=0;}}
if(s.time%20===0){let need=Math.ceil(population(c)/4);for(let k of ['bread','fish','grain']){let n=Math.min(need,c.stock[k]);c.stock[k]-=n;need-=n;}c.hunger=need?Math.min(c.hunger+1,5):Math.max(0,c.hunger-1);}}
for(const r of s.routes){if(r.paused)continue;const from=s.cities[r.from],to=s.cities[r.to];if(!from||!to)continue;if(r.travel>0){r.travel--;if(r.travel===0){let target=r.direction===0?to:from;let room=120-target.stock[r.good];let n=Math.min(room,r.cargo);target.stock[r.good]+=n;r.cargo-=n;s.deliveries+=n;if(r.cargo>0){r.blocked='Ziellager voll';}else{r.direction=1-r.direction;r.good=r.direction===0?r.out:r.back;r.blocked='';}}continue;}if(r.cargo>0){let target=r.direction===0?to:from;let n=Math.min(120-target.stock[r.good],r.cargo);target.stock[r.good]+=n;r.cargo-=n;s.deliveries+=n;if(!r.cargo){r.direction=1-r.direction;r.good=r.direction===0?r.out:r.back;}continue;}
let origin=r.direction===0?from:to;if(r.kind==='land'&&origin.stock.feed<1){r.blocked='Futter am Abfahrtsort fehlt';continue;}let good=r.direction===0?r.out:r.back;let amount=Math.min(r.amount,Math.max(0,origin.stock[good]-r.reserve-(r.kind==='land'&&good==='feed'?1:0)));if(amount===0){r.blocked='Wartet auf Waren / Mindestbestand';continue;}if(r.kind==='land')origin.stock.feed--;origin.stock[good]-=amount;r.good=good;r.cargo=amount;r.travel=r.duration;r.blocked='';}}
function found(s,id){if(![1,2].includes(id)||s.cities.some(c=>c.id===id))return 'Ort bereits gegründet.';if(id!==s.cities.length)return 'Gründe zuerst Salzwiek.';let cost={wood:16,plank:12};if(!afford(s.cities[0].stock,cost))return 'Zur Gründung brauchst du 16 Holz und 12 Bretter in Lindenhavn.';spend(s.cities[0].stock,cost);let c=city(id);c.stock.wood=16;c.stock.plank=8;c.stock.fish=16;c.stock.grain=4;s.cities.push(c);return '';}
function route(s,from,to,kind,out,back,amount=6,reserve=4){if(from===to||!s.cities[from]||!s.cities[to]||!GOODS[out]||!GOODS[back]||!['sea','land'].includes(kind))return 'Ungültige Route.';if(kind==='land'&&![from,to].every(i=>[0,2].includes(i)))return 'Der Landweg verbindet nur Lindenhavn und Lehmau.';if(!Number.isInteger(amount)||amount<1||amount>12||!Number.isInteger(reserve)||reserve<0||reserve>100)return 'Ungültige Ladungsmenge.';let cost=kind==='sea'?{wood:10,plank:8}:{wood:6,plank:4,feed:4};if(!afford(s.cities[from].stock,cost))return 'Baustoffe am Startort fehlen.';spend(s.cities[from].stock,cost);s.routes.push({from,to,kind,out,back,amount,reserve,direction:0,good:out,cargo:0,travel:0,duration:kind==='sea'?24:18,paused:false,blocked:''});return '';}
function upgrade(c){if(c.level)return 'Dorf bereits erreicht.';if(population(c)<20||c.stock.bread<8||!afford(c.stock,{plank:12})||c.hunger)return 'Benötigt: 20 Bewohner, 8 Brot, 12 Bretter und gesicherte Nahrung.';spend(c.stock,{bread:8,plank:12});c.level=1;return '';}
function parseSave(text){let s=JSON.parse(text);if(s.version!==1||!Array.isArray(s.cities)||s.cities.length<1||s.cities.length>3||!Array.isArray(s.routes))throw Error('Unbekanntes Speicherformat');for(const c of s.cities){if(!Array.isArray(c.buildings)||!c.stock||!Array.isArray(c.resources))throw Error('Spielstand beschädigt');for(const k of Object.keys(GOODS))if(!Number.isFinite(c.stock[k])||c.stock[k]<0)throw Error('Ungültiger Bestand');}return s;}
const api={GOODS,DEF,terrain,fresh,city,at,connected,linked,population,afford,place,status,tick,found,route,upgrade,parseSave,coast};if(typeof module!=='undefined')module.exports=api;root.Haven=api;
})(globalThis);
